@Override
public ImgBatchUploadResponseVo batchUpload(ImgBatchUploadRequestVo batchUploadVo) {
    ImgUtils.assertParameterNotNull(batchUploadVo, "batchUploadVo");
    ImgUtils.assertParameterNotNull(batchUploadVo.getBussVo(), "ImgBatchUploadVo.BussVo");
    ImgUtils.assertStringNotNull(batchUploadVo.getComCode(), "ImgBatchUploadVo.comCode");
    ImgUtils.assertStringNotNull(batchUploadVo.getOperator(), "ImgBatchUploadVo.operator");
    ImgBussVo bussVo = batchUploadVo.getBussVo();
    ImgUtils.assertStringNotNull(bussVo.getBussNo(), "ImgBatchUploadVo.ImgBussVo.BussNo");
    ImgUtils.assertStringNotNull(bussVo.getBussType(), "ImgBatchUploadVo.ImgBussVo.BussType");

    if (CollectionUtils.isNotEmpty(batchUploadVo.getUploadDataVos())) {
        List<ImgMetaDataVo> uploadDataVos = batchUploadVo.getUploadDataVos();
        List<ImgMetaDataVo> uploadedDataVoList = new ArrayList<>();

        for (ImgMetaDataVo uploadVo : uploadDataVos) {
            List<File> uploadFileList = getFilesToUpload(uploadVo.getUploadFile());

            for (File f : uploadFileList) {
                try {
                    Map<String, String> headerMap = new HashMap<>();
                    headerMap.put("bussNo", bussVo.getBussNo());
                    headerMap.put("bussType", bussVo.getBussType());
                    headerMap.put("orgFileName", URLEncoder.encode(f.getName(), "UTF-8"));
                    headerMap.put("imgType", uploadVo.getImgType());
                    String response = HttpClientUtil.executeFileByPOST(uploadDocUrl+batchUploadFileUrl, f, "file", headerMap);
                    CommonResponse<ImgMetaDataVo> claimCareResponse = JSON.parseObject(response, new TypeReference<CommonResponse<ImgMetaDataVo>>() {});
                    if (claimCareResponse.getSuccess() == 1) {
                        ImgMetaDataVo uploadedDataVo = createUploadedDataVo(uploadVo, f, claimCareResponse.getData());
                        uploadedDataVoList.add(uploadedDataVo);
                    } else {
                        log.error("上传失败原因：" + claimCareResponse.getErrorMessage());
                    }
                } catch (Exception e) {
                    log.error(e.getMessage());
                }
            }
        }
        batchUploadVo.setUploadDataVos(uploadedDataVoList);
    }

    ImgBatchUploadResponseVo responseVo = null;
    try {
        String batchResponse = HttpClientUtil.executeJSONByPOST(uploadDocUrl+batchUploadDataUrl, JSON.toJSONString(batchUploadVo));
        CommonResponse<ImgBatchUploadResponseVo> claimCareBatchResponse = JSON.parseObject(batchResponse, new TypeReference<CommonResponse<ImgBatchUploadResponseVo>>() {});
        responseVo = claimCareBatchResponse.getData();
    } catch (Exception e) {
        log.error(e.getMessage());
    }
    return responseVo;
}

private List<File> getFilesToUpload(File uploadFile) {
    List<File> uploadFileList = new ArrayList<>();
    if (uploadFile.isDirectory()) {

        if (uploadFile.isDirectory()) {
            File[] files = uploadFile.listFiles();
            if (files != null) {
                uploadFileList.addAll(Arrays.asList(files));
            }
        } else {
            uploadFileList.add(uploadFile);
        }
        return uploadFileList;
    }

    private ImgMetaDataVo createUploadedDataVo(ImgMetaDataVo uploadVo, File file, ImgMetaDataVo metaDataVo)
            throws Exception {
        ImgMetaDataVo uploadedDataVo = new ImgMetaDataVo();
        BeanUtils.copyProperties(uploadedDataVo, uploadVo);
        uploadedDataVo.setImgId(metaDataVo.getImgId());
        uploadedDataVo.setAppendPath(metaDataVo.getAppendPath());
        uploadedDataVo.setFileName(metaDataVo.getFileName());
        if (uploadedDataVo.getFileOrgName() == null) {
            uploadedDataVo.setFileOrgName(file.getName());
        }
        uploadedDataVo.setFileSize((double) file.length() / (double) 1024.0F);
        return uploadedDataVo;
    }

