 */
private String getFilePath(MultipartFile file, Integer docSourceType) {
    //文件后缀
    String fileSuffix = "." + ImageUtil.checkFile(file);
    /**
     * 文件类型不合法
     */
    if (isBlank(fileSuffix)) {
        throw new ExternalBusinessException("File.InvalidContentTypeException");
    }
    String fileName = "";
    if (docSourceType != null && DocSourceTypeEnum.parseValue(docSourceType) != null) {
        fileName = DocSourceTypeEnum.parseValue(docSourceType).getName() + "-" + DateUtils
            .sssToText(LocalDateTime.now())+UUID.randomUUID().toString().substring(0, 6)
            + fileSuffix;
    } else {
        /**
         * 生成新的文件名
         */
        fileName = "H5在线-" + DateUtils.sssToText(LocalDateTime.now())+UUID.randomUUID().toString().substring(0, 6) + fileSuffix;
    }
    try {
        fileName = Files.write2File(Files.TEMP_PATH + UUID.randomUUID().toString(), fileName, file.getBytes());
    } catch (Exception e) {
        log.error("write file error", e);
        throw new ExternalBusinessException("File.InvalidContentTypeException");
    }
    return fileName;
}

